// This file is generated by AI.

// 角色名到 GSOV 权重的自动配对测试。
//
// 配对只在**可信**时成立: 名称相同, 或一方包含另一方。配错的代价是"界面看起来已经
// 选好了, 音色却不对", 比不配难查得多, 因此歧义一律返回 null。

import { describe, expect, it } from 'vitest';

import type { ModelCandidate } from '../src/commands/voice';
import { pickModel } from '../src/voice/modelPair';

function model(name: string, key: string): ModelCandidate {
  return { name, key, gptWeights: `GPT/${name}.ckpt`, sovitsWeights: `SoVITS/${name}.pth` };
}

const anon = model('爱音-e15', '爱音');
const soyo = model('素世(夹)-e15', '素世(夹)');
const anonAscii = model('Anon_e4', 'anon');

describe('pickModel', () => {
  it('名称相同时配上', () => {
    expect(pickModel('爱音', [anon, soyo])).toBe(anon);
  });

  it('忽略大小写与空白', () => {
    expect(pickModel('  ANON ', [anonAscii, soyo])).toBe(anonAscii);
  });

  it('角色名包含模型名时配上 (千早爱音 / 爱音)', () => {
    expect(pickModel('千早爱音', [anon, soyo])).toBe(anon);
  });

  it('模型名包含角色名时配上', () => {
    const long = model('千早爱音-e15', '千早爱音');
    expect(pickModel('爱音', [long, soyo])).toBe(long);
  });

  it('对不上时不猜', () => {
    expect(pickModel('高松灯', [anon, soyo])).toBeNull();
  });

  it('单字模型名不参与包含匹配', () => {
    const single = model('音-e15', '音');
    expect(pickModel('千早爱音', [single])).toBeNull();
  });

  it('命中更长的一方优先', () => {
    const short = model('爱音-e15', '爱音');
    const long = model('千早爱音-e15', '千早爱音');
    expect(pickModel('千早爱音', [short, long])).toBe(long);
  });

  it('同等强度的多个候选视为有歧义', () => {
    const a = model('爱音-e15', '爱音');
    const b = model('音酱-e15', '音酱');
    expect(pickModel('爱音酱', [a, b])).toBeNull();
  });

  it('没有候选或空名称时返回 null', () => {
    expect(pickModel('爱音', [])).toBeNull();
    expect(pickModel('   ', [anon])).toBeNull();
  });
});
